create or replace function private.complete_post_job_followup(p_id uuid,p_status text,p_notes text default null) returns void language plpgsql security definer set search_path='' as $$ begin if not public.has_permission_for_current_user('view_csr') then raise exception 'CSR permission required'; end if; if p_status not in ('completed','dismissed') then raise exception 'Invalid status'; end if; update public.post_job_followups set status=p_status,completed_at=now(),notes=left(trim(coalesce(p_notes,'')),2000) where id=p_id and status='pending'; if not found then raise exception 'Follow-up is no longer pending'; end if; end $$; create or replace function public.complete_post_job_followup(p_id uuid,p_status text,p_notes text default null) returns void language sql set search_path='' as $$ select private.complete_post_job_followup(p_id,p_status,p_notes) $$; revoke all on function public.complete_post_job_followup(uuid,text,text) from public,anon; grant execute on function public.complete_post_job_followup(uuid,text,text) to authenticated; create or replace function private.csr_command_metrics() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not public.has_permission_for_current_user('view_csr') then raise exception 'CSR permission required'; end if; return jsonb_build_object('postJobDue',(select count(*) from public.post_job_followups where status='pending' and due_at<=now()),'qualityDue',(select count(*) from public.post_job_followups where status='pending' and followup_type='quality_check' and due_at<=now()),'membershipDue',(select count(*) from public.post_job_followups where status='pending' and followup_type='membership' and due_at<=now()),'estimateDue',(select count(*) from public.post_job_followups where status='pending' and followup_type='estimate' and due_at<=now()),'reviewDue',(select count(*) from public.post_job_followups where status='pending' and followup_type='review' and due_at<=now()),'estimatePipelineDue',(select count(*) from public.estimates where status in ('draft','sent') and follow_up_at is not null and follow_up_at<=now())); end $$; create or replace function public.csr_command_metrics() returns jsonb language sql stable set search_path='' as $$ select private.csr_command_metrics() $$; revoke all on function public.csr_command_metrics() from public,anon; grant execute on function public.csr_command_metrics() to authenticated;